  flex: 1;
  padding: 10px 14px;
  font-size: 16px;
  border: 1px solid #ccc;
  border-radius: 6px;
  outline: none;
  transition: border-color 0.2s;
}

#message-input:focus {
  border-color: #4a90d9;
}

#message-form button {
  padding: 10px 20px;
  font-size: 16px;
