  color: #fff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s;
}

#message-form button:hover {
  background-color: #357abd;
}

#message-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

